function isRawHtmlLine(line) {
  const trimmed = trimText(line);
  return trimmed.startsWith('<') && trimmed.endsWith('>');
}

function parseTableAlignmentCell(cell) {
  let trimmed = trimText(cell);
  if (trimmed.length === 0) {
    return null;
  }

  let left = false;
  let right = false;

