  let cursor = index + 2;
  while (cursor < lines.length && !isBlankLine(lines[cursor])) {
    if (lines[cursor].indexOf('|') === -1) {
      break;
    }
    body.push(splitPipeRow(lines[cursor]));
    cursor += 1;
