  const orderedFirst = parseOrderedListItem(lines[index]);
  const unorderedFirst = parseUnorderedListItem(lines[index]);
  if (orderedFirst === null && unorderedFirst === null) {
    return null;
  }

  const ordered = orderedFirst !== null;
  const items = [ordered ? orderedFirst : unorderedFirst];
  let cursor = index + 1;

  while (cursor < lines.length) {
    if (isBlankLine(lines[cursor])) {
      break;
    }

    const nextItem = ordered ? parseOrderedListItem(lines[cursor]) : parseUnorderedListItem(lines[cursor]);
    if (nextItem === null) {
      break;
    }

    items.push(nextItem);
    cursor += 1;
  }

  return {
    node: {
      type: ordered ? 'ordered_list' : 'unordered_list',
      items,
    },
    nextIndex: cursor,
  };
