function parseFencedCode(lines, index) {
  const fence = parseFenceStart(lines[index]);
  if (fence === null) {
    return null;
  }

  const codeLines = [];
  let cursor = index + 1;

  while (cursor < lines.length) {
    if (isFenceClose(lines[cursor], fence.fenceLength)) {
      cursor += 1;
      break;
    }
    codeLines.push(lines[cursor]);
    cursor += 1;
  }

  return {
    node: {
      type: 'fenced_code',
      language: fence.language,
      content: codeLines.join('\n'),
    },
    nextIndex: cursor,
  };
