  while (cursor < lines.length) {
    const line = lines[cursor];
    if (line.startsWith('\t') || countLeadingSpaces(line) >= 4) {
      codeLines.push(removeIndentedCodePrefix(line));
      cursor += 1;
      continue;
    }

    if (isBlankLine(line)) {
      codeLines.push('');
      cursor += 1;
      continue;
    }

    break;
  }

  return {
    node: {
      type: 'codehilite',
      content: codeLines.join('\n'),
    },
    nextIndex: cursor,
  };
}

function startsSpecialBlock(lines, index, options) {
  if (index >= lines.length || isBlankLine(lines[index])) {
    return true;
  }
  if (isRawHtmlLine(lines[index])) {
    return true;
  }
  if (options.fencedCode && parseFenceStart(lines[index]) !== null) {
    return true;
  }
  if (options.codeHilite && (lines[index].startsWith('\t') || countLeadingSpaces(lines[index]) >= 4)) {
    return true;
  }
  if (options.toc && trimText(lines[index]) === '[TOC]') {
    return true;
  }
  if (parseHeadingLine(lines[index]) !== null) {
    return true;
  }
  if (options.tables && tryParseTable(lines, index) !== null) {
    return true;
  }
  if (parseList(lines, index) !== null) {
    return true;
  }
  return false;
}

function parseBlocks(lines, options) {
  const nodes = [];
  let index = 0;

  while (index < lines.length) {
    if (isBlankLine(lines[index])) {
      index += 1;
      continue;
    }

    if (isRawHtmlLine(lines[index])) {
      const htmlLines = [];
      let cursor = index;
