}

function slugify(text) {
  let slug = '';
  let lastWasDash = false;
  const lower = text.toLowerCase();

  for (let i = 0; i < lower.length; i += 1) {
    const char = lower[i];
    const isLetter = char >= 'a' && char <= 'z';
    const isDigit = char >= '0' && char <= '9';
    const isSeparator = char === ' ' || char === '\t' || char === '\n' || char === '-' || char === '_';

    if (isLetter || isDigit) {
      slug += char;
      lastWasDash = false;
      continue;
    }

    if (isSeparator && !lastWasDash && slug.length > 0) {
      slug += '-';
      lastWasDash = true;
    }
