}

function buildTocTree(headings) {
  const root = {
    level: 0,
    children: [],
  };
  const stack = [root];

  for (let i = 0; i < headings.length; i += 1) {
    const heading = headings[i];
    while (stack.length > 1 && stack[stack.length - 1].level >= heading.level) {
      stack.pop();
    }

    const parent = stack[stack.length - 1];
    const node = {
      level: heading.level,
      id: heading.id,
      text: heading.text,
      children: [],
    };

    parent.children.push(node);
    stack.push(node);
  }

  return root.children;
}

function renderTocList(items) {
  if (items.length === 0) {
    return '<ul></ul>';
  }

  const lines = ['<ul>'];
  for (let i = 0; i < items.length; i += 1) {
    const item = items[i];
    if (item.children.length === 0) {
      lines.push(`<li><a href="#${escapeAttribute(item.id)}">${escapeHtmlText(item.text)}</a></li>`);
      continue;
    }

    lines.push(`<li><a href="#${escapeAttribute(item.id)}">${escapeHtmlText(item.text)}</a>${renderTocList(item.children)}`);
    lines.push('</li>');
  }
  lines.push('</ul>');
  return lines.join('\n');
}

function renderToc(headings) {
  return `<div class="toc">\n${renderTocList(buildTocTree(headings))}\n</div>`;
}

function renderAlignmentAttribute(alignment) {
  if (alignment === null) {
    return '';
  }
  return ` style="text-align: ${alignment};"`;
}

function normalizeRowLength(cells, expectedLength) {
  const normalized = [];
  for (let i = 0; i < expectedLength; i += 1) {
    normalized.push(i < cells.length ? cells[i] : '');
  }
  return normalized;
}

function renderTable(node) {
  const lines = ['<table>', '<thead>', '<tr>'];
  for (let i = 0; i < node.headers.length; i += 1) {
    lines.push(`<th${renderAlignmentAttribute(node.alignments[i])}>${renderInline(node.headers[i])}</th>`);
  }
  lines.push('</tr>', '</thead>', '<tbody>');

  for (let rowIndex = 0; rowIndex < node.rows.length; rowIndex += 1) {
    const row = normalizeRowLength(node.rows[rowIndex], node.headers.length);
    lines.push('<tr>');
    for (let cellIndex = 0; cellIndex < row.length; cellIndex += 1) {
      lines.push(`<td${renderAlignmentAttribute(node.alignments[cellIndex])}>${renderInline(row[cellIndex])}</td>`);
    }
    lines.push('</tr>');
  }

  lines.push('</tbody>', '</table>');
  return lines.join('\n');
}

function renderFencedCode(node) {
  const classAttribute = node.language.length > 0 ? ` class="language-${escapeAttribute(node.language)}"` : '';
  return `<pre><code${classAttribute}>${escapeHtmlText(node.content)}\n</code></pre>`;
}

function renderCodeHilite(node) {
  return `<div class="codehilite"><pre><span></span><code>${escapeHtmlText(node.content)}\n</code></pre></div>`;
}

function renderList(node) {
  const tagName = node.type === 'ordered_list' ? 'ol' : 'ul';
  const lines = [`<${tagName}>`];
  for (let i = 0; i < node.items.length; i += 1) {
    lines.push(`<li>${renderInline(node.items[i])}</li>`);
  }
  lines.push(`</${tagName}>`);
  return lines.join('\n');
}

function renderNodes(nodes, headings, options) {
  const parts = [];

  for (let i = 0; i < nodes.length; i += 1) {
    const node = nodes[i];
    if (node.type === 'raw_html') {
      parts.push(node.html);
    } else if (node.type === 'paragraph') {
      parts.push(`<p>${renderInline(node.text)}</p>`);
    } else if (node.type === 'heading') {
      const idAttribute = options.toc ? ` id="${escapeAttribute(node.id)}"` : '';
      parts.push(`<h${node.level}${idAttribute}>${renderInline(node.text)}</h${node.level}>`);
    } else if (node.type === 'ordered_list' || node.type === 'unordered_list') {
      parts.push(renderList(node));
    } else if (node.type === 'table') {
      parts.push(renderTable(node));
    } else if (node.type === 'fenced_code') {
      parts.push(renderFencedCode(node));
    } else if (node.type === 'codehilite') {
      parts.push(renderCodeHilite(node));
    } else if (node.type === 'toc') {
      parts.push(renderToc(headings));
    }
  }

  return parts.join('\n');
}

export function renderMarkdown(source, extensions = []) {
  const options = resolveExtensions(extensions);
  const normalizedSource = normalizeLineEndings(source);
  const lines = normalizedSource.split('\n');
  const nodes = parseBlocks(lines, options);
  const headings = assignHeadingIds(nodes, options);
  return renderNodes(nodes, headings, options);
}

