const REQUIRED_OPTIONS = ['a', 'b', 'c'];

function getProgramName(argv) {
  const raw = argv.length > 1 ? argv[1] : 'test13.mjs';
  return basename(raw);
}

function basename(pathValue) {
  let lastSlash = -1;
  for (let i = 0; i < pathValue.length; i += 1) {
    const char = pathValue[i];
    if (char === '/' || char === '\\') {
      lastSlash = i;
    }
  }
  if (lastSlash === -1) {
    return pathValue;
  }
  return pathValue.slice(lastSlash + 1);
}

function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

function formatHelp(programName) {
  return `${formatUsage(programName)}\n\nMarkdown with extension configuration\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C\n`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}`;
}

function isKnownOptionName(token) {
  return token === '--a' || token === '--b' || token === '--c';
}

function splitInlineValue(token) {
  if (!token.startsWith('--')) {
    return null;
  }

  let equalsIndex = -1;
  for (let i = 2; i < token.length; i += 1) {
    if (token[i] === '=') {
      equalsIndex = i;
      break;
    }
  }

  if (equalsIndex === -1) {
    return null;
  }

  return {
    name: token.slice(0, equalsIndex),
    value: token.slice(equalsIndex + 1),
  };
}

function isDigit(char) {
  return char >= '0' && char <= '9';
}

function isNegativeNumber(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  let index = 1;
  let seenDigit = false;
  let seenDot = false;

  if (token[index] === '.') {
    seenDot = true;
    index += 1;
  }

  for (; index < token.length; index += 1) {
    const char = token[index];
    if (isDigit(char)) {
      seenDigit = true;
      continue;
    }
    if (char === '.' && !seenDot) {
