      if (parsedValue.kind === 'error') {
        return {
          kind: 'error',
          errorText: parsedValue.errorText,
          exitCode: 2,
        };
      }
      values[token.slice(2)] = parsedValue.value;
      index = parsedValue.nextIndex;
      continue;
    }

    extras.push(token);
    index += 1;
  }

  const missing = missingRequired(values);
  if (missing.length > 0) {
    return {
      kind: 'error',
      errorText: formatError(programName, `the following arguments are required: ${missing.join(', ')}`),
