export function normalizeLineEndings(value) {
  let normalized = '';
  for (let i = 0; i < value.length; i += 1) {
    const char = value[i];
    if (char === '\r') {
      if (i + 1 < value.length && value[i + 1] === '\n') {
        i += 1;
      }
      normalized += '\n';
      continue;
    }
    normalized += char;
  }
  return normalized;
}

export function isBlankLine(line) {
  for (let i = 0; i < line.length; i += 1) {
    const char = line[i];
    if (char !== ' ' && char !== '\t') {
      return false;
    }
  }
  return true;
}

export function trimText(value) {
  return value.trim();
}

export function escapeHtmlText(value) {
  let escaped = '';
  for (let i = 0; i < value.length; i += 1) {
    const char = value[i];
    if (char === '&') {
      escaped += '&amp;';
    } else if (char === '<') {
      escaped += '&lt;';
    } else if (char === '>') {
      escaped += '&gt;';
    } else {
      escaped += char;
    }
  }
  return escaped;
}

export function escapeAttribute(value) {
  let escaped = '';
  for (let i = 0; i < value.length; i += 1) {
    const char = value[i];
    if (char === '&') {
      escaped += '&amp;';
    } else if (char === '<') {
      escaped += '&lt;';
    } else if (char === '>') {
      escaped += '&gt;';
    } else if (char === '"') {
      escaped += '&quot;';
    } else {
      escaped += char;
    }
  }
  return escaped;
}

export function splitPipeRow(line) {
  let working = trimText(line);
  if (working.startsWith('|')) {
    working = working.slice(1);
  }
  if (working.endsWith('|')) {
    working = working.slice(0, working.length - 1);
  }

  const cells = [];
  let cell = '';

  for (let i = 0; i < working.length; i += 1) {
    const char = working[i];
    if (char === '|' && (i === 0 || working[i - 1] !== '\\')) {
      cells.push(trimText(cell));
      cell = '';
      continue;
    }
    cell += char;
  }

  cells.push(trimText(cell));
  return cells;
}

export function countLeadingSpaces(line) {
  let count = 0;
  while (count < line.length && line[count] === ' ') {
    count += 1;
  }
  return count;
}

export function removeIndentedCodePrefix(line) {
  if (line.startsWith('\t')) {
    return line.slice(1);
  }
  if (countLeadingSpaces(line) >= 4) {
    return line.slice(4);
  }
  return line;
}

