import { basename, formatError, formatHelp, parseArguments } from './lib/cli/argparse.mjs';
import {
  renderCodeHiliteMarkdown,
  renderDefaultMarkdown,
  renderExtraTablesMarkdown,
  renderFencedTocMarkdown,
} from './lib/markdown/index.mjs';

export function main(argv = process.argv.slice(2)) {
  const programName = basename(process.argv[1]);
  const parsed = parseArguments(argv, programName);

  if (parsed.help) {
    process.stdout.write(formatHelp(programName));
    return 0;
  }

  if (parsed.error) {
    process.stderr.write(formatError(programName, parsed.error));
    return 2;
  }

  const html1 = renderExtraTablesMarkdown(parsed.values.a);
  const html2 = renderCodeHiliteMarkdown(parsed.values.b);
  const html3 = renderFencedTocMarkdown(parsed.values.c);
  const combined = renderDefaultMarkdown(`${html1}\n${html2}\n${html3}`);

  process.stdout.write(`${html1}\n`);
  process.stdout.write(`${html2}\n`);
  process.stdout.write(`${html3}\n`);
  process.stdout.write(`${combined}\n`);
  return 0;
}

